INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter BIOS?', 2, '[{"text": "Firmware für den Systemstart", "correct": true, "because": "Steuert Bootprozess"}, {"text": "Betriebssystem", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem BIOS?', 3, '[{"text": "Initialisierung der Hardware", "correct": true, "because": "Startet Computer"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat das BIOS?', 5, '[{"text": "POST (Power-On Self-Test)", "correct": true, "because": "Hardwareprüfung"}, {"text": "Bootloader starten", "correct": true, "because": "Betriebssystem laden"}, {"text": "Textformatierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BIOS ist auf dem Mainboard gespeichert. b) Es ist ein Betriebssystem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Firmware, kein OS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim BIOS?', 4, '[{"text": "Hardwareinitialisierung", "correct": false, "because": "Kernaufgabe"}, {"text": "Bootreihenfolge", "correct": false, "because": "Konfiguration wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das BIOS den POST durchführt?', 2, '[{"text": "Ja", "correct": true, "because": "Power-On Self-Test"}, {"text": "Nein", "correct": false, "because": "Standardfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Taste wird oft verwendet, um ins BIOS zu gelangen?', 3, '[{"text": "DEL", "correct": true, "because": "Häufige Standardtaste"}, {"text": "Enter", "correct": false, "because": "Keine BIOS-Taste"}, {"text": "Space", "correct": false, "because": "Kein Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Konfiguration im BIOS?', 5, '[{"text": "Bootreihenfolge", "correct": true, "because": "Startmedium wählen"}, {"text": "CPU-Einstellungen", "correct": true, "because": "Overclocking möglich"}, {"text": "Marketingplan", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das BIOS startet das Betriebssystem. b) Es ist nur für Windows nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle OS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim BIOS unwichtig?', 4, '[{"text": "Hardwareerkennung", "correct": false, "because": "Kernfunktion"}, {"text": "Bootprozess", "correct": false, "because": "Hauptaufgabe"}, {"text": "Farbe des Bildschirms", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das BIOS aktualisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Firmware-Update"}, {"text": "Nein", "correct": false, "because": "Möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modernes BIOS?', 4, '[{"text": "Schnellerer Bootprozess", "correct": true, "because": "Effizienz"}, {"text": "Bessere Hardwareunterstützung", "correct": true, "because": "Kompatibilität"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das BIOS veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "UEFI ergänzt, BIOS bleibt"}, {"text": "Ja", "correct": false, "because": "Noch genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim BIOS?', 3, '[{"text": "Bootfähigkeit", "correct": true, "because": "Hauptfunktion"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BIOS führt den POST aus. b) Es ist nur für alte Systeme relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch moderne Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein veraltetes BIOS?', 5, '[{"text": "Fehlende Hardwareunterstützung", "correct": true, "because": "Neue Geräte"}, {"text": "Langsamerer Bootprozess", "correct": true, "because": "Ineffizienz"}, {"text": "Schnellere Reaktion", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim BIOS?', 3, '[{"text": "Konfiguration und Updates", "correct": true, "because": "Sichert Betrieb"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das BIOS UEFI ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "UEFI ist Nachfolger"}, {"text": "Ja", "correct": false, "because": "Unterschiedlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für BIOS-Updates nutzen?', 4, '[{"text": "BIOS-Update-Utility", "correct": true, "because": "Herstellersoftware"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
